-- These procedures already exist in the database. Call them.
-- Do not recreate them, and do not change them.

CREATE OR REPLACE PROCEDURE sp_part1(para_Roller_Coaster_ID integer, para_Height real, para_Park text, para_Country_ID integer, para_Languages text) LANGUAGE plpgsql AS
$$
DECLARE
    var1 integer;
    var2 text;
BEGIN
    var1 := para_Roller_Coaster_ID;
    var2 := 'init';
    IF var1 < 10 THEN
        UPDATE "roller_coaster" SET "Roller_Coaster_ID" = para_Roller_Coaster_ID + para_Height WHERE "Roller_Coaster_ID" = para_Roller_Coaster_ID;
        UPDATE "country" SET "Languages" = para_Languages WHERE "Country_ID" = para_Roller_Coaster_ID;
        var2 := 'low';
    ELSIF var1 < 20 THEN
        DELETE FROM "country" WHERE "Country_ID" = para_Country_ID;
        INSERT INTO "country" ("Country_ID", "Languages") VALUES (para_Country_ID, para_Languages);
        var2 := 'mid';
    ELSIF var1 < 30 THEN
        UPDATE "roller_coaster" SET "Park" = para_Park || '_' || "Roller_Coaster_ID" WHERE "Roller_Coaster_ID" > 0;
        var2 := 'high';
    ELSIF var1 < 40 THEN
        UPDATE "country" SET "Languages" = "Languages" || 'X' WHERE "Country_ID" IN (SELECT "Roller_Coaster_ID" FROM "roller_coaster");
        var2 := 'veryhigh';
    ELSE
        UPDATE "roller_coaster" SET "Height" = 'default' WHERE "Roller_Coaster_ID" = para_Roller_Coaster_ID;
        var2 := 'reset';
    END IF;
    IF para_Park IS NOT NULL THEN
        UPDATE "roller_coaster" SET "Park" = var2 || '_' || para_Park WHERE "Roller_Coaster_ID" = para_Roller_Coaster_ID;
    ELSE
        DELETE FROM "country" WHERE "Country_ID" = para_Country_ID;
    END IF;
END;
$$;

CREATE OR REPLACE PROCEDURE sp_part2(para_Roller_Coaster_ID integer, para_New_Country_ID integer, para_Name text) LANGUAGE plpgsql AS
$$
BEGIN
    UPDATE "roller_coaster" SET "Country_ID" = para_New_Country_ID WHERE "Roller_Coaster_ID" = para_Roller_Coaster_ID;
    UPDATE "country" SET "Name" = para_Name WHERE "Country_ID" = para_New_Country_ID;
END;
$$;

