CREATE OR REPLACE PROCEDURE sp(para_Roller_Coaster_ID integer, para_Country_ID integer, para_Park text, para_Height real, para_Languages text, para_New_Country_ID integer, para_Name text)
LANGUAGE plpgsql
AS $$
DECLARE
    v_count integer;
BEGIN
    SELECT COUNT(*) INTO v_count
    FROM "roller_coaster"
    WHERE "Roller_Coaster_ID" = para_Roller_Coaster_ID
      AND "Country_ID" = para_Country_ID;

    IF v_count > 0 THEN
        CALL sp_part1(para_Roller_Coaster_ID, para_Height, para_Park, para_Country_ID, para_Languages);

        IF para_Height > 50 THEN
            CALL sp_part2(para_Roller_Coaster_ID, para_New_Country_ID, para_Name);
        ELSIF para_Height <= 50 THEN
            IF EXISTS (SELECT 1 FROM "country" WHERE "Country_ID" = para_New_Country_ID) THEN
                UPDATE "country"
                SET "Population" = "Population" + 1000
                WHERE "Country_ID" = para_New_Country_ID;
            ELSE
                INSERT INTO "country" ("Country_ID", "Name", "Population")
                VALUES (para_New_Country_ID, para_Name, 1000);
            END IF;
        END IF;
    ELSE
        IF para_Park IS NULL THEN
            INSERT INTO "roller_coaster" ("Roller_Coaster_ID", "Name", "Park", "Country_ID", "Height")
            VALUES (para_Roller_Coaster_ID, para_Name, NULL, para_New_Country_ID, para_Height);
        ELSE
            CALL sp_part2(para_Roller_Coaster_ID, para_New_Country_ID, para_Name);

            UPDATE "roller_coaster"
            SET "Name" = para_Name
            WHERE "Roller_Coaster_ID" = para_Roller_Coaster_ID;
        END IF;

        CALL sp_part1(para_Roller_Coaster_ID, para_Height, para_Park, para_Country_ID, para_Languages);
    END IF;
END;
$$;

